 * The scanner. `lex(source)` turns UTF-8 source text into a list of tokens, or
 * throws a `LexError` carrying the position and the reason of the first fault.
 */

export class LexError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.name = 'LexError'
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = [
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) =>
  c !== undefined && ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdentStart = (c) => isLetter(c) || c === '_'
const isIdentPart = (c) => isIdentStart(c) || isDigit(c)

export function lex(source) {
  const cp = Array.from(source)
  const n = cp.length
  let i = 0
  let line = 1
  let column = 1
  const tokens = []

  const at = (k = 0) => cp[i + k]

  function advance() {
    const c = cp[i]
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column += 4 - ((column - 1) % 4)
    } else {
      column += 1
    }
    i += 1
    return c
  }

  const textFrom = (start) => cp.slice(start, i).join('')

  while (i < n) {
    const c = at()

    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance()
      continue
    }

    if (c === '/' && at(1) === '/') {
      while (i < n && at() !== '\n') advance()
      continue
    }

    if (c === '/' && at(1) === '*') {
      const sl = line
      const sc = column
      let depth = 0
      while (i < n) {
        if (at() === '/' && at(1) === '*') {
          advance()
          advance()
          depth += 1
        } else if (at() === '*' && at(1) === '/') {
          advance()
          advance()
          depth -= 1
          if (depth === 0) break
        } else {
          advance()
        }
      }
      if (depth !== 0) throw new LexError(sl, sc, 'unterminated block comment')
      continue
    }

    const sl = line
    const sc = column
    const start = i

    // Raw strings, before identifiers, since they open with `r"`.
    if (c === 'r' && at(1) === '"') {
      advance()
      advance()
      let value = ''
      let closed = false
      while (i < n) {
        if (at() === '"') {
          advance()
          closed = true
          break
        }
        value += advance()
      }
      if (!closed) throw new LexError(sl, sc, 'unterminated string')
      tokens.push({ line: sl, column: sc, kind: 'rawstring', text: textFrom(start), value })
      continue
    }

    if (isIdentStart(c)) {
      while (i < n && isIdentPart(at())) advance()
      const text = textFrom(start)
      const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
      tokens.push({ line: sl, column: sc, kind, text, value: text })
      continue
    }

    if (isDigit(c)) {
      let valid = true

      const runOf = (pred) => {
        let count = 0
        let lastDigit = false
        for (;;) {
          const d = at()
          if (pred(d)) {
            advance()
            count += 1
            lastDigit = true
          } else if (d === '_' && lastDigit && pred(at(1))) {
            advance()
            lastDigit = false
          } else {
            break
          }
        }
        return count
      }

      const prefix = at(1)
      if (c === '0' && (prefix === 'x' || prefix === 'X')) {
        advance()
        advance()
        if (runOf(isHex) === 0) valid = false
      } else if (c === '0' && (prefix === 'b' || prefix === 'B')) {
        advance()
        advance()
        if (runOf(isBin) === 0) valid = false
      } else if (c === '0' && (prefix === 'o' || prefix === 'O')) {
        advance()
        advance()
        if (runOf(isOct) === 0) valid = false
      } else {
        runOf(isDigit)
        if (at() === '.' && isDigit(at(1))) {
          advance()
          runOf(isDigit)
        }
        const e = at()
        if (e === 'e' || e === 'E') {
          if (isDigit(at(1))) {
            advance()
            runOf(isDigit)
          } else if ((at(1) === '+' || at(1) === '-') && isDigit(at(2))) {
            advance()
            advance()
            runOf(isDigit)
          }
        }
      }

      if (isIdentPart(at())) {
        valid = false
        while (i < n && isIdentPart(at())) advance()
      }

      const text = textFrom(start)
      if (!valid) throw new LexError(sl, sc, `invalid number ${text}`)
      tokens.push({ line: sl, column: sc, kind: 'number', text, value: text })
      continue
    }

    if (c === '"') {
      advance()
      let value = ''
      let closed = false
      while (i < n) {
        const d = at()
        if (d === '"') {
          advance()
          closed = true
          break
        }
        if (d === '\n') throw new LexError(line, column, 'newline in string')
        if (d === '\\') {
          const bl = line
          const bc = column
          if (at(1) === undefined) {
            advance()
            break
          }
          if (at(1) === '\n') {
            advance()
            throw new LexError(line, column, 'newline in string')
          }
          advance()
          const esc = advance()
          if (esc === 'n') value += '\n'
          else if (esc === 't') value += '\t'
          else if (esc === 'r') value += '\r'
          else if (esc === '\\') value += '\\'
          else if (esc === '"') value += '"'
          else if (esc === '0') value += '\0'
          else if (esc === 'x') {
            if (!isHex(at()) || !isHex(at(1))) throw new LexError(bl, bc, 'invalid escape \\x')
            const h = advance() + advance()
            value += String.fromCharCode(parseInt(h, 16))
          } else if (esc === 'u') {
            if (at() !== '{' || !isHex(at(1))) throw new LexError(bl, bc, 'invalid escape \\u')
            advance()
            let h = ''
            while (isHex(at())) h += advance()
            if (at() !== '}') throw new LexError(bl, bc, 'invalid escape \\u')
            advance()
            const code = parseInt(h, 16)
            if (!(code <= 0x10ffff)) throw new LexError(bl, bc, 'invalid escape \\u')
            value += String.fromCodePoint(code)
          } else {
            throw new LexError(bl, bc, `invalid escape \\${esc}`)
          }
          continue
        }
        value += advance()
      }
      if (!closed) throw new LexError(sl, sc, 'unterminated string')
      tokens.push({ line: sl, column: sc, kind: 'string', text: textFrom(start), value })
      continue
    }

    const two = c + (at(1) === undefined ? '' : at(1))
    if (PUNCT2.includes(two)) {
      advance()
      advance()
      tokens.push({ line: sl, column: sc, kind: 'punct', text: two, value: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      advance()
      tokens.push({ line: sl, column: sc, kind: 'punct', text: c, value: c })
      continue
    }

    throw new LexError(sl, sc, `unexpected character ${c}`)
  }

  return tokens
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
"}

