{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import fs from 'node:fs'
import { lex, LexError, KINDS } from './lexer.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const buffer = Buffer.alloc(65536)
  for (;;) {
    let read
    try {
      read = fs.readSync(0, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (read === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, read)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'tokens' && mode !== 'stats')) {
    fail('usage: cli.js tokens|stats')
  }

  const source = readStdin()

  let tokens
  try {
    tokens = lex(source)
  } catch (error) {
    if (error instanceof LexError) fail(`${error.line}:${error.column}: ${error.reason}`)
    throw error
  }

  const lines = []
  if (mode === 'tokens') {
    for (const token of tokens) {
      const body =
        token.kind === 'string' || token.kind === 'rawstring'
          ? JSON.stringify(token.value)
          : token.text
      lines.push(`${token.line}:${token.column} ${token.kind} ${body}`)
    }
  } else {
    for (const kind of KINDS) {
      lines.push(`${kind} ${tokens.filter((token) => token.kind === kind).length}`)
    }
    lines.push(`total ${tokens.length}`)
  }
  process.stdout.write(lines.map((entry) => `${entry}\n`).join(''))
}

main(process.argv.slice(2))
"}

